const N=t=>{if(!t)return null;const r=String(t).match(/^(\d{2})-(\d{2})-(\d{4})(?:\s+(\d{1,2}):(\d{2})\s*(AM|PM)?)?$/i);if(!r){const a=new Date(t);return isNaN(a.getTime())?null:a}const[,u,m,s,d="0",o="0",n]=r;let e=Number(d);n&&(n.toUpperCase()==="PM"&&e!==12&&(e+=12),n.toUpperCase()==="AM"&&e===12&&(e=0));const i=new Date(Number(s),Number(m)-1,Number(u),e,Number(o));return isNaN(i.getTime())?null:i};export{N as p};
